CREATE TABLE ezcontentobject_link (id INT AUTO_INCREMENT NOT NULL, contentclassattribute_id INT DEFAULT 0 NOT NULL, from_contentobject_id INT DEFAULT 0 NOT NULL, from_contentobject_version INT DEFAULT 0 NOT NULL, relation_type INT DEFAULT 1 NOT NULL, to_contentobject_id INT DEFAULT 0 NOT NULL, INDEX ezco_link_to_co_id (to_contentobject_id), INDEX ezco_link_from (from_contentobject_id, from_contentobject_version, contentclassattribute_id), INDEX ezco_link_cca_id (contentclassattribute_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
